"""Behaviour of the calendar feature helper ``calc_time_stamps``."""

import pandas as pd
import pytest

from sktime.libs.kronos.kronos import calc_time_stamps

EXPECTED_COLUMNS = ["minute", "hour", "weekday", "day", "month"]


def _series(start, periods, freq="h", **kwargs):
    return pd.Series(pd.date_range(start, periods=periods, freq=freq), **kwargs)


def test_returns_the_five_calendar_columns_in_order():
    stamps = calc_time_stamps(_series("2024-05-06 07:08", periods=2))

    assert isinstance(stamps, pd.DataFrame)
    assert list(stamps.columns) == EXPECTED_COLUMNS


def test_values_match_the_timestamps():
    x_timestamp = pd.Series(
        pd.to_datetime(
            [
                "2024-01-31 23:58:00",  # Wednesday, last minute of January
                "2024-02-01 00:00:00",  # Thursday, first minute of February
                "2024-02-04 13:45:00",  # Sunday
            ]
        )
    )

    stamps = calc_time_stamps(x_timestamp)

    assert stamps["minute"].tolist() == [58, 0, 45]
    assert stamps["hour"].tolist() == [23, 0, 13]
    assert stamps["weekday"].tolist() == [2, 3, 6]
    assert stamps["day"].tolist() == [31, 1, 4]
    assert stamps["month"].tolist() == [1, 2, 2]


def test_row_count_and_index_follow_the_input_series():
    x_timestamp = _series("2024-03-01", periods=1, freq="min")
    x_timestamp = pd.concat([x_timestamp, _series("2024-03-01 00:01", periods=1)])
    x_timestamp.index = ["first", "second"]

    stamps = calc_time_stamps(x_timestamp)

    assert len(stamps) == 2
    assert stamps.index.tolist() == ["first", "second"]
    assert stamps.loc["second", "minute"] == 1


def test_weekday_values_stay_within_bounds():
    stamps = calc_time_stamps(_series("2024-01-01", periods=24 * 7, freq="h"))

    assert stamps["weekday"].between(0, 6).all()
    assert stamps["hour"].between(0, 23).all()
    assert stamps["minute"].between(0, 59).all()


def test_empty_input_returns_empty_frame_with_all_columns():
    stamps = calc_time_stamps(pd.Series([], dtype="datetime64[ns]"))

    assert stamps.shape == (0, len(EXPECTED_COLUMNS))
    assert list(stamps.columns) == EXPECTED_COLUMNS


def test_non_datetime_input_is_rejected():
    with pytest.raises(AttributeError):
        calc_time_stamps(["2024-01-01 00:00:00"])
"""Behaviour of the token filtering and sampling helpers.

The helpers operate on ``torch`` tensors.  Since ``torch`` is optional, the
tests drive them through the deterministic numpy-backed tensor stub defined in
``_torch_stub.py`` and assert the *contract* of the helpers: which logits
survive filtering, which token index is returned, and how the bounds are
clamped.
"""

import sys
from pathlib import Path

import numpy as np
import pytest

sys.path.insert(0, str(Path(__file__).parent))

from _torch_stub import FakeTensor, TorchStub  # noqa: E402

from sktime.libs.kronos import kronos  # noqa: E402

NEG_INF = -np.inf


@pytest.fixture
def stub(monkeypatch):
    torch_stub = TorchStub()
    monkeypatch.setattr(kronos, "torch", torch_stub.torch)
    monkeypatch.setattr(kronos, "F", torch_stub.functional)
    return torch_stub


def _logits(values):
    return FakeTensor(np.array([values], dtype=np.float64))


def _kept(tensor):
    return np.isfinite(np.asarray(tensor))


# ------------------------------------------------------- top_k_top_p_filtering
def test_top_k_keeps_only_the_k_largest_logits(stub):
    logits = _logits([3.0, 1.0, 0.5, 0.1])

    result = kronos.top_k_top_p_filtering(logits, top_k=2, top_p=1.0)

    assert result is logits
    np.testing.assert_array_equal(_kept(logits), [[True, True, False, False]])
    assert logits.array[0, 0] == 3.0
    assert logits.array[0, 3] == NEG_INF


def test_top_k_is_clamped_to_the_vocabulary_size(stub):
    logits = _logits([3.0, 1.0, 0.5, 0.1])

    kronos.top_k_top_p_filtering(logits, top_k=99, top_p=1.0)

    assert _kept(logits).all()


def test_top_k_honours_min_tokens_to_keep(stub):
    logits = _logits([3.0, 1.0, 0.5, 0.1])

    kronos.top_k_top_p_filtering(logits, top_k=2, top_p=1.0, min_tokens_to_keep=3)

    assert _kept(logits).sum() == 3


def test_top_k_wins_over_top_p_when_both_are_given(stub):
    logits = _logits([3.0, 1.0, 0.5, 0.1])

    kronos.top_k_top_p_filtering(logits, top_k=1, top_p=0.99)

    assert _kept(logits).sum() == 1


def test_no_filtering_returns_none_and_leaves_logits_untouched(stub):
    logits = _logits([3.0, 1.0, 0.5, 0.1])

    result = kronos.top_k_top_p_filtering(logits, top_k=0, top_p=1.0)

    assert result is None
    np.testing.assert_allclose(logits.array[0], [3.0, 1.0, 0.5, 0.1])


def test_nucleus_filtering_keeps_the_minimal_probability_mass(stub):
    # softmax([3, 1, .5, .1]) ~= [.786, .106, .064, .043]
    # cumulative mass reaches 0.9 only with the three largest logits
    logits = _logits([3.0, 1.0, 0.5, 0.1])

    kronos.top_k_top_p_filtering(logits, top_k=0, top_p=0.9)

    np.testing.assert_array_equal(_kept(logits), [[True, True, True, False]])


def test_aggressive_top_p_keeps_only_the_best_token(stub):
    logits = _logits([3.0, 1.0, 0.5, 0.1])

    kronos.top_k_top_p_filtering(logits, top_k=0, top_p=0.7)

    np.testing.assert_array_equal(_kept(logits), [[True, False, False, False]])


def test_min_tokens_to_keep_widens_the_nucleus(stub):
    logits = _logits([5.0, 4.0, 3.0, 2.0, 1.0, 0.0])

    kronos.top_k_top_p_filtering(logits, top_k=0, top_p=0.1)
    baseline = _kept(logits).sum()

    logits = _logits([5.0, 4.0, 3.0, 2.0, 1.0, 0.0])
    kronos.top_k_top_p_filtering(logits, top_k=0, top_p=0.1, min_tokens_to_keep=2)

    assert baseline == 1
    assert _kept(logits).sum() > baseline
    np.testing.assert_array_equal(
        _kept(logits), [[True, True, True, False, False, False]]
    )


def test_custom_filter_value_is_used(stub):
    logits = _logits([3.0, 1.0, 0.5, 0.1])

    kronos.top_k_top_p_filtering(logits, top_k=1, filter_value=-1e9)

    np.testing.assert_allclose(logits.array[0], [3.0, -1e9, -1e9, -1e9])


def test_rows_are_filtered_independently(stub):
    logits = FakeTensor(np.array([[3.0, 1.0, 0.5], [0.1, 0.5, 3.0]]))

    kronos.top_k_top_p_filtering(logits, top_k=1, top_p=1.0)

    np.testing.assert_array_equal(
        _kept(logits), [[True, False, False], [False, False, True]]
    )


# ----------------------------------------------------------- sample_from_logits
def test_greedy_sampling_returns_the_argmax(stub):
    logits = _logits([3.0, 1.0, 7.5, 0.1])

    sampled = kronos.sample_from_logits(
        logits, temperature=1.0, top_k=0, top_p=1.0, sample_logits=False
    )

    np.testing.assert_array_equal(np.asarray(sampled), [[2]])


def test_sampling_returns_a_single_token_per_row(stub):
    logits = FakeTensor(np.zeros((2, 5)))

    sampled = kronos.sample_from_logits(logits, temperature=1.0)

    assert np.asarray(sampled).shape == (2, 1)
    assert np.asarray(sampled).min() >= 0
    assert np.asarray(sampled).max() <= 4


def test_peaked_distribution_is_sampled_reliably(stub):
    logits = _logits([0.0, 0.0, 60.0, 0.0])

    for _ in range(10):
        sampled = kronos.sample_from_logits(logits, temperature=1.0)
        np.testing.assert_array_equal(np.asarray(sampled), [[2]])


def test_low_temperature_makes_sampling_deterministic(stub):
    logits = _logits([1.0, 1.5])

    sampled = kronos.sample_from_logits(logits, temperature=0.01)

    np.testing.assert_array_equal(np.asarray(sampled), [[1]])


def test_high_temperature_exposes_low_probability_tokens(stub):
    logits = _logits([1.0, 1.5])

    draws = {
        int(np.asarray(kronos.sample_from_logits(logits, temperature=1e6)).ravel()[0])
        for _ in range(40)
    }

    assert draws == {0, 1}


def test_sampling_without_filtering_accepts_none_thresholds(stub):
    logits = _logits([0.0, 0.0, 60.0, 0.0])

    sampled = kronos.sample_from_logits(logits, top_k=None, top_p=None)

    np.testing.assert_array_equal(np.asarray(sampled), [[2]])


def test_sampling_respects_the_requested_top_k(stub):
    logits = _logits([0.0, 0.0, 60.0, 0.0])

    sampled = kronos.sample_from_logits(logits, top_k=2, top_p=1.0)

    # top_k=2 keeps the two largest logits: token 2 and one of the zero-logits
    assert int(np.asarray(sampled).ravel()[0]) in {0, 1, 2}
