"""Behaviour of ``KronosPredictor`` preprocessing and postprocessing.

``torch`` is an optional dependency.  The predictor only needs torch to move
tensors to a device and to call ``auto_regressive_inference``, so the tests
below replace ``torch`` with the numpy backed stub in ``_torch_stub.py`` and
replace the autoregressive sampler with a recording double.  This isolates the
predictor's own contract: validation, normalisation, de-normalisation, column
handling and argument forwarding.
"""

import sys
from pathlib import Path
from unittest import mock

import numpy as np
import pandas as pd
import pytest

sys.path.insert(0, str(Path(__file__).parent))

from _torch_stub import TorchStub  # noqa: E402

from sktime.libs.kronos import kronos  # noqa: E402

PRICE_COLS = ["open", "high", "low", "close"]
ALL_COLS = PRICE_COLS + ["volume", "amount"]


# --------------------------------------------------------------------- helpers
class _RecordingModule:
    """Stand-in for a tokenizer / model that only records ``.to`` calls."""

    def __init__(self):
        self.devices = []

    def to(self, device):
        self.devices.append(device)
        return self


class _InferenceSpy:
    """Recording double for ``auto_regressive_inference``."""

    def __init__(self, fill=0.0):
        self.fill = fill
        self.calls = []

    def __call__(
        self,
        tokenizer,
        model,
        x,
        x_stamp,
        y_stamp,
        max_context,
        pred_len,
        clip,
        T,
        top_k,
        top_p,
        sample_count,
        verbose,
    ):
        x = np.asarray(x)
        self.calls.append(
            {
                "tokenizer": tokenizer,
                "model": model,
                "x": x.copy(),
                "x_stamp": np.asarray(x_stamp).copy(),
                "y_stamp": np.asarray(y_stamp).copy(),
                "max_context": max_context,
                "pred_len": pred_len,
                "clip": clip,
                "T": T,
                "top_k": top_k,
                "top_p": top_p,
                "sample_count": sample_count,
                "verbose": verbose,
            }
        )
        batch, seq_len, n_feat = x.shape
        return np.full((batch, seq_len + pred_len, n_feat), self.fill, dtype=np.float32)

    @property
    def last(self):
        return self.calls[-1]


def _patch_torch(monkeypatch, cuda=False, mps=False):
    stub = TorchStub(cuda_available=cuda, mps_available=mps)
    monkeypatch.setattr(kronos, "torch", stub.torch)
    monkeypatch.setattr(kronos, "F", stub.functional)
    return stub


@pytest.fixture
def inference_spy(monkeypatch):
    spy = _InferenceSpy()
    monkeypatch.setattr(kronos, "auto_regressive_inference", spy)
    return spy


@pytest.fixture
def predictor(monkeypatch, inference_spy):
    _patch_torch(monkeypatch)

    model = _RecordingModule()
    tokenizer = _RecordingModule()
    predictor = kronos.KronosPredictor(model=model, tokenizer=tokenizer)
    predictor.test_model = model
    predictor.test_tokenizer = tokenizer
    return predictor


def _frame(n=8, base=100.0, volume=True, amount=False):
    step = np.arange(n, dtype=np.float64)
    df = pd.DataFrame(
        {
            "open": base + step,
            "high": base + step + 1.5,
            "low": base + step - 1.25,
            "close": base + step + 0.5,
        }
    )
    if volume:
        df["volume"] = 10.0 + step
    if amount:
        df["amount"] = 1000.0 + step
    return df


def _timestamps(start, periods, freq="h"):
    return pd.Series(pd.date_range(start, periods=periods, freq=freq))


# ----------------------------------------------------------- construction
def test_device_defaults_to_cpu_and_moves_both_modules(predictor):
    assert predictor.device == "cpu"
    assert predictor.test_model.devices == ["cpu"]
    assert predictor.test_tokenizer.devices == ["cpu"]


def test_cuda_is_preferred_when_available(monkeypatch, inference_spy):
    _patch_torch(monkeypatch, cuda=True, mps=True)
    model, tokenizer = _RecordingModule(), _RecordingModule()

    predictor = kronos.KronosPredictor(model=model, tokenizer=tokenizer)

    assert predictor.device == "cuda:0"
    assert model.devices == ["cuda:0"]
    assert tokenizer.devices == ["cuda:0"]


def test_mps_used_when_cuda_is_unavailable(monkeypatch, inference_spy):
    _patch_torch(monkeypatch, cuda=False, mps=True)
    model, tokenizer = _RecordingModule(), _RecordingModule()

    predictor = kronos.KronosPredictor(model=model, tokenizer=tokenizer)

    assert predictor.device == "mps"


def test_explicit_device_overrides_detection(monkeypatch, inference_spy):
    _patch_torch(monkeypatch, cuda=True)
    model, tokenizer = _RecordingModule(), _RecordingModule()

    predictor = kronos.KronosPredictor(
        model=model, tokenizer=tokenizer, device="cpu", max_context=32, clip=3
    )

    assert predictor.device == "cpu"
    assert model.devices == ["cpu"]
    assert predictor.max_context == 32
    assert predictor.clip == 3


