"""Lightweight numpy-backed stand-ins for the optional ``torch`` dependency.

The Kronos module soft-imports ``torch``.  When ``torch`` is not installed,
sktime replaces it with a ``MagicMock``-like placeholder, which makes the
tensor code in ``sktime.libs.kronos`` unusable and untestable.

This module provides a small, deterministic, numpy-backed imitation of the
subset of the ``torch`` API that ``sktime.libs.kronos`` uses for *inference*
(no autograd, no devices).  It is only used to test the observable contract of
the module - which tokens are kept by the filters, how buffers are rolled, what
values are fed back into the model - never to replace the numerics of torch.
"""

import contextlib

import numpy as np

__all__ = [
    "FakeTensor",
    "FakeFunctional",
    "FakeTorch",
    "TorchStub",
    "FakeTokenizer",
    "FakeKronosModel",
]


def _unwrap(value):
    """Return the raw numpy array behind ``value``."""
    if isinstance(value, FakeTensor):
        return value.array
    return value


class FakeTensor:
    """Minimal numpy-backed imitation of ``torch.Tensor``."""

    def __init__(self, array):
        self.array = np.asarray(array)
        self.device = None

    # ------------------------------------------------------------------ dunder
    def __array__(self, dtype=None):
        return self.array if dtype is None else self.array.astype(dtype)

    def __repr__(self):  # pragma: no cover - debugging helper
        return f"FakeTensor({self.array!r})"

    def __getitem__(self, key):
        return FakeTensor(self.array[_unwrap(key)])

    def __setitem__(self, key, value):
        self.array[_unwrap(key)] = _unwrap(value)

    def __truediv__(self, other):
        return FakeTensor(self.array / _unwrap(other))

    def __mul__(self, other):
        return FakeTensor(self.array * _unwrap(other))

    def __add__(self, other):
        return FakeTensor(self.array + _unwrap(other))

    def __sub__(self, other):
        return FakeTensor(self.array - _unwrap(other))

    def __pow__(self, other):
        return FakeTensor(self.array ** _unwrap(other))

    def __rpow__(self, other):
        return FakeTensor(np.asarray(other) ** self.array)

    def __and__(self, other):
        return FakeTensor(self.array & _unwrap(other))

    def __rshift__(self, other):
        return FakeTensor(self.array >> _unwrap(other))

    def __ne__(self, other):
        return FakeTensor(self.array != _unwrap(other))

    def __lt__(self, other):
        return FakeTensor(self.array < _unwrap(other))

    def __gt__(self, other):
        return FakeTensor(self.array > _unwrap(other))

    # ------------------------------------------------------------- shape/info
    @property
    def shape(self):
        return self.array.shape

    def size(self, dim=None):
        if dim is None:
            return self.array.size
        return self.array.shape[dim]

    def dim(self):
        return self.array.ndim

    # ------------------------------------------------------------- conversions
    def to(self, device):
        self.device = device
        return self

    def cpu(self):
        return self

    def numpy(self):
        return self.array

    def contiguous(self):
        return self

    def clone(self):
        return FakeTensor(self.array.copy())

    def sum(self, axis=None, dim=None):
        return FakeTensor(self.array.sum(axis=axis if axis is not None else dim))

    def detach(self):
        return self

    def float(self):
        return FakeTensor(self.array.astype(np.float64))

    def long(self):
        return FakeTensor(self.array.astype(np.int64))

    def type_as(self, other):
        return FakeTensor(self.array.astype(_unwrap(other).dtype))

    # ------------------------------------------------------------- reshapes
    def unsqueeze(self, dim):
        return FakeTensor(np.expand_dims(self.array, dim))

    def squeeze(self, dim=None):
        return FakeTensor(np.squeeze(self.array, axis=dim))

    def reshape(self, *shape):
        if len(shape) == 1 and isinstance(shape[0], (tuple, list)):
            shape = tuple(shape[0])
        return FakeTensor(self.array.reshape(shape))

    view = reshape

    def repeat(self, *reps):
        if len(reps) == 1 and isinstance(reps[0], (tuple, list)):
            reps = tuple(reps[0])
        return FakeTensor(np.tile(self.array, reps))

    # ------------------------------------------------------------- in-place
    def copy_(self, other):
        self.array[...] = _unwrap(other)
        return self

    def new_empty(self, *shape):
        return FakeTensor(np.zeros(shape, dtype=self.array.dtype))

    def new_zeros(self, *shape):
        return FakeTensor(np.zeros(shape, dtype=self.array.dtype))

    def scatter(self, dim, index, src):
        out = self.array.copy()
        np.put_along_axis(out, _unwrap(index), _unwrap(src), axis=dim)
        return FakeTensor(out)


class FakeFunctional:
    """Imitation of ``torch.nn.functional``."""

    @staticmethod
    def softmax(tensor, dim=-1):
        array = _unwrap(tensor).astype(np.float64)
        shifted = array - array.max(axis=dim, keepdims=True)
        exp = np.exp(shifted)
        return FakeTensor(exp / exp.sum(axis=dim, keepdims=True))

    @staticmethod
    def normalize(tensor, dim=-1):
        array = _unwrap(tensor).astype(np.float64)
        norm = np.linalg.norm(array, axis=dim, keepdims=True)
        return FakeTensor(array / norm)


class _FakeCuda:
    def __init__(self, available):
        self.available = available

    def is_available(self):
        return self.available


class _FakeMps:
    def __init__(self, available):
        self.available = available

    def is_available(self):
        return self.available


class _FakeBackends:
    def __init__(self, mps_available):
        self.mps = _FakeMps(mps_available)


class FakeTorch:
    """Imitation of the top-level ``torch`` module used by kronos."""

    long = "int64"

    def __init__(self, cuda_available=False, mps_available=False, seed=0):
        self.cuda = _FakeCuda(cuda_available)
        self.backends = _FakeBackends(mps_available)
        self.rng = np.random.default_rng(seed)
        self.from_numpy_calls = []

    # ---------------------------------------------------------------- creation
    def from_numpy(self, array):
        tensor = FakeTensor(np.array(array))
        self.from_numpy_calls.append(tensor)
        return tensor

    def tensor(self, value):
        return FakeTensor(np.asarray(value))

    def zeros(self, *shape):
        return FakeTensor(np.zeros(shape))

    def ones(self, *shape):
        return FakeTensor(np.ones(shape))

    def arange(self, *args, **kwargs):
        dtype = np.int64 if kwargs.get("dtype") == "int64" else None
        return FakeTensor(np.arange(*args, dtype=dtype))

    # ---------------------------------------------------------------- numerical
    def clip(self, tensor, min=None, max=None):
        return FakeTensor(np.clip(_unwrap(tensor), min, max))

    def cat(self, tensors, dim=0):
        return FakeTensor(np.concatenate([_unwrap(t) for t in tensors], axis=dim))

    def roll(self, tensor, shifts, dims):
        return FakeTensor(np.roll(_unwrap(tensor), shift=shifts, axis=dims))

    def cumsum(self, tensor, dim=-1):
        return FakeTensor(np.cumsum(_unwrap(tensor), axis=dim))

    def sort(self, tensor, dim=-1, descending=False):
        array = _unwrap(tensor)
        if descending:
            indices = np.argsort(-array, axis=dim, kind="stable")
        else:
            indices = np.argsort(array, axis=dim, kind="stable")
        values = np.take_along_axis(array, indices, axis=dim)
        return FakeTensor(values), FakeTensor(indices)

    def topk(self, tensor, k, dim=-1):
        array = _unwrap(tensor)
        indices = np.argsort(-array, axis=dim, kind="stable")
        indices = np.take(indices, np.arange(k), axis=dim)
        values = np.take_along_axis(array, indices, axis=dim)
        return FakeTensor(values), FakeTensor(indices)

    def multinomial(self, probs, num_samples=1):
        array = np.asarray(_unwrap(probs), dtype=np.float64)
        flat = array.reshape(-1, array.shape[-1])
        flat = flat / flat.sum(axis=-1, keepdims=True)
        draws = np.array(
            [
                min(
                    int(np.searchsorted(np.cumsum(row), self.rng.random(), side="right")),
                    row.shape[0] - 1,
                )
                for row in flat
            ]
        )
        out = draws.reshape(array.shape[:-1] + (num_samples,))
        return FakeTensor(out.astype(np.int64))

    # ------------------------------------------------------------------ misc
    @staticmethod
    def no_grad():
        return contextlib.nullcontext()


class TorchStub:
    """Bundle of the fake ``torch`` module and ``torch.nn.functional``."""

    def __init__(self, cuda_available=False, mps_available=False, seed=0):
        self.torch = FakeTorch(
            cuda_available=cuda_available, mps_available=mps_available, seed=seed
        )
        self.functional = FakeFunctional()


class FakeTokenizer:
    """Deterministic stand-in for ``KronosTokenizer`` for inference tests."""

    def __init__(self, s1_ids, s2_ids):
        self.s1_ids = np.asarray(s1_ids)
        self.s2_ids = np.asarray(s2_ids)
        self.encode_calls = []
        self.decode_calls = []
        self.device = None

    def to(self, device):
        self.device = device
        return self

    def encode(self, x, half=True):
        x = np.asarray(x)
        self.encode_calls.append(x)
        batch = x.shape[0]
        s1 = np.tile(self.s1_ids, (batch, 1))
        s2 = np.tile(self.s2_ids, (batch, 1))
        return [FakeTensor(s1), FakeTensor(s2)]

    def decode(self, token_ids, half=True):
        pre, post = (np.asarray(t) for t in token_ids)
        self.decode_calls.append((pre.copy(), post.copy()))
        stacked = np.stack([pre, post], axis=-1).astype(np.float64)
        return FakeTensor(stacked)


class FakeKronosModel:
    """Deterministic stand-in for ``Kronos`` for inference tests."""

    def __init__(self, vocab_s1=8, vocab_s2=8):
        self.vocab_s1 = vocab_s1
        self.vocab_s2 = vocab_s2
        self.decode_s1_calls = []
        self.decode_s2_calls = []
        self.device = None

    def to(self, device):
        self.device = device
        return self

    @staticmethod
    def _one_hot(batch, length, index, vocab):
        logits = np.zeros((batch, length, vocab), dtype=np.float64)
        logits[:, -1, index % vocab] = 50.0
        return FakeTensor(logits)

    def decode_s1(self, s1_ids, s2_ids, stamp=None, padding_mask=None):
        s1_ids = np.asarray(s1_ids)
        stamp_arr = None if stamp is None else np.asarray(stamp).copy()
        self.decode_s1_calls.append((s1_ids.copy(), stamp_arr, s1_ids.shape[1]))
        batch, length = s1_ids.shape
        context = FakeTensor(np.zeros((batch, length, 1), dtype=np.float64))
        return self._one_hot(batch, length, length, self.vocab_s1), context

    def decode_s2(self, context, s1_ids, padding_mask=None):
        s1_ids = np.asarray(s1_ids)
        self.decode_s2_calls.append(s1_ids.copy())
        batch, length = s1_ids.shape
        return self._one_hot(batch, length, length, self.vocab_s2)

