"""Tests for :mod:`sktime.libs.timer_s1.ts_generation_mixin`.

``TSGenerationMixin`` adapts the Hugging Face generation loop to time-series
patches.  The generation loop itself is exercised through the model class; here
the observable contract of the mixin is tested: bookkeeping of the model
keyword arguments between generation steps, and re-normalisation of forecast
samples in :meth:`TSGenerationMixin.generate`.
"""

import importlib
import importlib.util
import types

import numpy as np
import pytest

MIXIN_MODULE = "sktime.libs.timer_s1.ts_generation_mixin"


def _torch_stack_is_usable():
    """Whether the module was built on a real torch/transformers stack."""
    if (
        importlib.util.find_spec("torch") is None
        or importlib.util.find_spec("transformers") is None
    ):
        return False
    module = importlib.import_module(MIXIN_MODULE)
    if not isinstance(getattr(module, "torch", None), types.ModuleType):
        return False
    return isinstance(getattr(module, "GenerationMixin", None), type)


requires_model_stack = pytest.mark.skipif(
    not _torch_stack_is_usable(),
    reason="torch and transformers are required to run the generation loop",
)


class _Array(np.ndarray):
    """Array with the handful of methods the mixin calls on tensors."""

    def new_ones(self, shape):
        return np.ones(shape, dtype=self.dtype).view(_Array)

    def unsqueeze(self, dim):
        return np.expand_dims(self, axis=dim).view(_Array)

    def to(self, device):
        return self


class _CatOnlyTorch:
    """Stand-in for the ``torch`` module restricted to concatenation."""

    @staticmethod
    def cat(tensors, dim=0):
        return np.concatenate([np.asarray(t) for t in tensors], axis=dim).view(_Array)


class _ModelOutput:
    """Minimal stand-in for a Hugging Face ``ModelOutput``."""

    def __init__(self, **fields):
        self._fields = dict(fields)

    def __contains__(self, key):
        return key in self._fields

    def __getattr__(self, name):
        try:
            return self._fields[name]
        except KeyError:
            raise AttributeError(name) from None


def _tensor(values, dtype=np.float64):
    return np.asarray(values, dtype=dtype).view(_Array)


@pytest.fixture
def mixin(monkeypatch):
    """Yield a mixin instance whose torch usage is backed by numpy arrays."""
    module = importlib.import_module(MIXIN_MODULE)
    monkeypatch.setattr(module, "torch", _CatOnlyTorch)
    return module.TSGenerationMixin()


