    module = importlib.import_module(MIXIN_MODULE)
    captured = {}

    def _fake_generate(self, inputs=None, **kwargs):
        captured["inputs"] = inputs.detach().clone()
        captured["kwargs"] = kwargs
        return inputs.clone()

    monkeypatch.setattr(module.GenerationMixin, "generate", _fake_generate)
    inputs = torch.tensor([[1.0, 2.0, 3.0, 4.0], [10.0, 20.0, 30.0, 40.0]])

