    normalised = captured["inputs"]
    assert torch.allclose(normalised.mean(dim=-1), torch.zeros(2), atol=1e-6)
    assert torch.allclose(
        normalised.std(dim=-1, unbiased=False), torch.ones(2), atol=1e-4
    )
    assert torch.allclose(outputs, inputs, atol=1e-6)


