from sktime.libs.timesfm.xreg_lib import (
    BatchedInContextXRegBase,
    BatchedInContextXRegLinear,
    _repeat,
    _to_padded_jax_array,
    _unnest,
)


class _FakeRandom:
    @staticmethod
    def PRNGKey(seed):
        return seed

    @staticmethod
    def choice(key, n, shape, replace=False):
        assert replace is False
        return np.arange(shape[0]) % n


class _FakeDefaultDevice:
    def __init__(self, device):
        self.device = device

    def __enter__(self):
        return None

    def __exit__(self, *args):
        return False


class _FakeJax:
    random = _FakeRandom
    default_device = _FakeDefaultDevice


@pytest.fixture
def numpy_jax(monkeypatch):
    monkeypatch.setattr(xreg_lib, "jnp", np)
    monkeypatch.setattr(xreg_lib, "jax", _FakeJax)


def test_unnest_and_repeat_flatten_ragged_values():
    nested = [np.array([1, 2]), np.array([3])]

    np.testing.assert_array_equal(_unnest(nested), [1, 2, 3])
    np.testing.assert_array_equal(_repeat([10, 20], [2, 1]), [10, 10, 20])


@pytest.mark.parametrize(
    ("array", "expected"),
    [
        (np.array([1, 2, 3]), np.array([1, 2, 3, 0])),
        (
            np.ones((3, 2)),
            np.array([[1, 1], [1, 1], [1, 1], [0, 0]]),
        ),
    ],
)
def test_to_padded_jax_array_pads_to_power_of_two(numpy_jax, array, expected):
    padded = _to_padded_jax_array(array)

    np.testing.assert_array_equal(padded, expected)


def test_to_padded_jax_array_rejects_more_than_two_dimensions(numpy_jax):
    with pytest.raises(ValueError, match="Unsupported array shape"):
        _to_padded_jax_array(np.ones((2, 2, 2)))


def test_init_defaults_unset_covariates_to_empty_dicts():
    model = BatchedInContextXRegBase(
        targets=[np.array([1.0])], train_lens=[1], test_lens=[1]
    )

    assert model.train_dynamic_numerical_covariates == {}
    assert model.train_dynamic_categorical_covariates == {}
    assert model.test_dynamic_numerical_covariates == {}
    assert model.test_dynamic_categorical_covariates == {}
    assert model.static_numerical_covariates == {}
    assert model.static_categorical_covariates == {}


def test_create_covariate_matrix_normalizes_numeric_dynamic_features():
    model = BatchedInContextXRegBase(
        targets=[np.array([1.0, 2.0]), np.array([3.0])],
        train_lens=[2, 1],
        test_lens=[1, 1],
        train_dynamic_numerical_covariates={
            "x": [np.array([1.0, 2.0]), np.array([3.0])]
        },
        test_dynamic_numerical_covariates={
            "x": [np.array([4.0]), np.array([5.0])]
        },
    )

    targets, x_train, x_test = model.create_covariate_matrix()

    np.testing.assert_array_equal(targets, [1.0, 2.0, 3.0])
    np.testing.assert_array_equal(x_train[:, 0], [1.0, 1.0, 1.0])
    np.testing.assert_allclose(x_train[:, 1].mean(), 0.0)
    np.testing.assert_allclose(x_train[:, 1].std(), 1.0)
    np.testing.assert_allclose(x_test[:, 0], [1.0, 1.0])
    np.testing.assert_allclose(x_test[:, 1], [6**0.5, (3 / 2) ** 0.5 * 3])


def test_create_covariate_matrix_repeats_static_numeric_covariates():
    model = BatchedInContextXRegBase(
        targets=[np.array([1.0, 2.0]), np.array([3.0])],
        train_lens=[2, 1],
        test_lens=[1, 2],
        static_numerical_covariates={"s": [0.0, 10.0]},
    )

    _, x_train, x_test = model.create_covariate_matrix(use_intercept=False)

    np.testing.assert_allclose(x_train[:, 0], [-2**-0.5, -2**-0.5, 2**0.5])
    np.testing.assert_allclose(x_test[:, 0], [-2**-0.5, 2**0.5, 2**0.5])


def test_create_covariate_matrix_encodes_dynamic_and_static_categories():
    model = BatchedInContextXRegBase(
        targets=[np.array([1.0, 2.0]), np.array([3.0])],
        train_lens=[2, 1],
        test_lens=[2, 1],
        train_dynamic_categorical_covariates={
            "c": [np.array(["a", "b"]), np.array(["a"])]
        },
        test_dynamic_categorical_covariates={
            "c": [np.array(["a", "z"]), np.array(["b"])]
        },
        static_categorical_covariates={"sc": ["x", "y"]},
    )

    with pytest.warns(UserWarning, match="unknown categories"):
        _, x_train, x_test = model.create_covariate_matrix(use_intercept=False)

    np.testing.assert_array_equal(x_train, [[0, 0], [1, 0], [0, 1]])
    np.testing.assert_array_equal(x_test, [[0, 0], [0, 0], [1, 1]])


def test_create_covariate_matrix_can_keep_all_category_levels():
    model = BatchedInContextXRegBase(
        targets=[np.array([1.0, 2.0]), np.array([3.0])],
        train_lens=[2, 1],
        test_lens=[2, 1],
        train_dynamic_categorical_covariates={
            "c": [np.array(["a", "b"]), np.array(["a"])]
        },
        test_dynamic_categorical_covariates={
            "c": [np.array(["a", "a"]), np.array(["b"])]
        },
    )

    _, x_train, x_test = model.create_covariate_matrix(
        one_hot_encoder_drop=None, use_intercept=False
    )

    np.testing.assert_array_equal(x_train, [[1, 0], [0, 1], [1, 0]])
    np.testing.assert_array_equal(x_test, [[1, 0], [1, 0], [0, 1]])


@pytest.mark.parametrize(
    ("covariate_kwargs", "message"),
    [
        (
            {"train_dynamic_numerical_covariates": {"x": [np.array([1.0])]}},
            "train_dynamic_numerical_covariates and test_dynamic",
        ),
        (
            {"train_dynamic_categorical_covariates": {"x": [np.array(["a"])]}},
            "train_dynamic_categorical_covariates and test_dynamic",
        ),
    ],
)
def test_assert_covariates_requires_matching_presence(covariate_kwargs, message):
    model = BatchedInContextXRegBase(
        targets=[np.array([1.0])],
        train_lens=[1],
        test_lens=[1],
        **covariate_kwargs,
    )

    with pytest.raises(ValueError, match=message):
