def test_linear_fit_recovers_linear_relationship(numpy_jax):
    model = BatchedInContextXRegLinear(
        targets=[np.array([1.0, 3.0, 5.0]), np.array([1.0, 3.0])],
        train_lens=[3, 2],
        test_lens=[2, 2],
        train_dynamic_numerical_covariates={
            "x": [np.array([0.0, 1.0, 2.0]), np.array([0.0, 1.0])]
        },
        test_dynamic_numerical_covariates={
            "x": [np.array([3.0, 4.0]), np.array([2.0, 3.0])]
        },
    )

    outputs = model.fit()

    assert len(outputs) == 2
    np.testing.assert_allclose(outputs[0], [7.0, 9.0])
    np.testing.assert_allclose(outputs[1], [5.0, 7.0])


def test_linear_fit_debug_info_returns_context_predictions_and_padded_arrays(
    numpy_jax,
):
    targets = [np.array([1.0, 3.0, 5.0]), np.array([1.0, 3.0])]
    model = BatchedInContextXRegLinear(
        targets=targets,
        train_lens=[3, 2],
        test_lens=[2, 2],
        train_dynamic_numerical_covariates={
            "x": [np.array([0.0, 1.0, 2.0]), np.array([0.0, 1.0])]
        },
        test_dynamic_numerical_covariates={
            "x": [np.array([3.0, 4.0]), np.array([2.0, 3.0])]
        },
    )

    outputs, outputs_context, flat_targets, x_train, x_test = model.fit(
        debug_info=True
    )

    assert len(outputs) == 2
    assert len(outputs_context) == 2
    np.testing.assert_allclose(np.concatenate(outputs_context), np.concatenate(targets))
    np.testing.assert_allclose(flat_targets[:5], np.concatenate(targets))
    assert x_train.shape == (8, 2)
    assert x_test.shape == (4, 2)
